func (p *libraryPackageImpl) initializeGenGoAnnotations(ecoreFactory ecore.EcoreFactory) {
	source := "http://net.masagroup/soft/2019/GenGo"
	{
		eAnnotation := ecoreFactory.CreateEAnnotationFromContainer(p)
		eAnnotation.SetSource(source)
		eAnnotation.GetDetails().Put("supressAnnotations", "http://www.eclipse.org/emf/2002/Ecore http://net.masagroup/soft/2018/GenCpp http://net.masagroup/soft/2020/GenTS")
	}
	{
		eAnnotation := ecoreFactory.CreateEAnnotationFromContainer(p.GetWriter())
		eAnnotation.SetSource(source)
		eAnnotation.GetDetails().Put("extension", "true")
	}
}
